text:
{
  "title_novice": "Зона возмущения: за ней пласт «не знает»",
  "summary": [
    {"text": "Давление в пласте меняется всё слабее с удалением от места возмущения, поэтому можно выделить зону возмущения.", "claims": ["c3", "c5"]},
    {"text": "Вне этой зоны течение считают невозмущённым: давление остаётся равным начальному значению.", "claims": ["c1"]},
    {"text": "Граница зоны условна: это приближение, а её размер растёт со временем.", "claims": ["c3", "c1"]}
  ],
  "claims": [
    {"key": "c1", "text": "Вне зоны возмущения течение можно считать невозмущённым: начальные значения давления или скорости сохраняются.", "kind": "assumption", "unit_id": "u-047-783935", "page": 47, "quote": "вне которой течение можно считать невозмущенным, т. е. сохраняются начальные значения $p$ или $u$", "numbers": [], "question": null},
    {"key": "c2", "text": "Существование такой области автор выводит из анализа точных решений этого параграфа.", "kind": "inference", "unit_id": "u-047-783935", "page": 47, "quote": "Возможность введения такой области следует из анализа точных решений, приведенных в настоящем параграфе", "numbers": [], "question": null},
    {"key": "c3", "text": "Отклонение давления от начального значения убывает с ростом расстояния x по закону exp(-x²/(4κt)).", "kind": "inference", "unit_id": "u-047-783935", "page": 47, "quote": "отклонение от начального убывает с ростом $x$ как $\\exp(-x^2/4xt)$", "numbers": ["2", "4"], "question": null},
    {"key": "c4", "text": "Метод интегральных соотношений — один из наиболее общих приближённых методов в теории фильтрации.", "kind": "observation", "unit_id": "u-047-783935", "page": 47, "quote": "Одним из наиболее общих приближенных методов в теории фильтрации является метод интегральных соотношений", "numbers": [], "question": null},
    {"key": "c5", "text": "В приближённых методах используют понятие области влияния или области возмущения.", "kind": "observation", "unit_id": "u-047-783935", "page": 47, "quote": "используется понятие области влияния или области возмущения", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Отклонение давления зависит от расстояния x и времени t в комбинации x²/(κt): это видно из показателя экспоненты.", "claims": ["c3"], "hypothesis": false},
    {"text": "Чем дальше точка от места возмущения, тем меньше отклонение от начального давления, и убывание идёт быстро.", "claims": ["c3"], "hypothesis": false},
    {"text": "Поэтому можно провести условную границу: за ней отклонение считают малым, а течение — невозмущённым.", "claims": ["c5", "c1"], "hypothesis": false},
    {"text": "Так как в показателе стоит κt, размер зоны растёт пропорционально √(κt), а не линейно с временем.", "claims": ["c3"], "hypothesis": false},
    {"text": "Физически давление передаётся соседним частям пласта с затуханием, а не как волна с постоянной скоростью.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "В приближённых методах зону возмущения используют, чтобы решить, где давление ещё меняется, а где его можно считать начальным.", "claims": ["c5", "c1"], "hypothesis": false},
    {"text": "На практике оценивают, на каком расстоянии отклонение ещё заметно, по коэффициенту пьезопроводности и времени.", "claims": [], "hypothesis": true},
    {"text": "Аналитическая оценка сводится к проверке, мал ли множитель exp(-x²/(4κt)) при выбранных x и t.", "claims": ["c3"], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Граница зоны условна: её задают для удобства приближённого решения, а не как физический фронт.", "claims": ["c1"], "hypothesis": false},
    {"text": "Понятие опирается на точные решения этого параграфа, а не на доказательство для любых пластов.", "claims": ["c2"], "hypothesis": false},
    {"text": "Экспонента никогда не становится точно нулём, поэтому отклонение лишь приближается к нулю, но не равно нулю.", "claims": ["c3"], "hypothesis": false},
    {"text": "Для другой геометрии пласта или других граничных условий вид затухания может отличаться от приведённого.", "claims": [], "hypothesis": true},
    {"text": "Метод интегральных соотношений — один из общих приближённых методов; его разбор дан в следующем узле.", "claims": ["c4"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Аналогия с прогревом стержня", "text": "Прогрев одного конца стержня тоже даёт зону, где температура почти не меняется. Граница такой зоны тоже условна.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие: вне зоны течение считают невозмущённым, сохраняются начальные значения p или u.", "claims": ["c1"]},
    {"text": "Отклонение убывает как exp(-x²/(4κt)): чем больше x при данном t, тем меньше отклонение.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "зона возмущения (область влияния)", "term_en": "disturbance zone (area of influence)", "abbr": "", "definition": "Область пласта, где давление уже отклонилось от начального значения. Вне её течение считают невозмущённым.", "claims": ["c5", "c1"]},
    {"term": "метод интегральных соотношений", "term_en": "integral relations method", "abbr": "", "definition": "Один из наиболее общих приближённых методов в теории фильтрации. Подробный разбор дан в следующем узле.", "claims": ["c4"]}
  ],
  "terms_used": [
    "нестационарная фильтрация",
    "коэффициент пьезопроводности",
    "отклонение давления от стационарного",
    "стационарное распределение давления",
    "масштаб √(κt)",
    "приближённое решение",
    "начальное условие"
  ],
  "formulas": [
    {"unit_id": "u-047-783935", "label": "", "latex": "\\exp\\left(-\\dfrac{x^2}{4\\varkappa t}\\right)", "meaning": "Множитель, по которому отклонение давления от начального значения убывает с ростом расстояния x.", "variables": [
      {"symbol": "x", "meaning": "расстояние от точки возмущения", "unit": "единица длины (в тексте не указана)"},
      {"symbol": "κ", "meaning": "коэффициент пьезопроводности (см. узел n02)", "unit": "единица площади на единицу времени"},
      {"symbol": "t", "meaning": "время с момента возмущения", "unit": "единица времени (в тексте не указана)"}
    ]}
