  "misconception": {"pack_id": "M16", "wrong": "Зона возмущения растёт с постоянной скоростью, как звук, и имеет резкий фронт.", "right": "Отклонение давления плавно убывает с расстоянием. Граница зоны условна, а её размер растёт пропорционально √(κt), а не линейно.", "claims": ["c3", "c1"]},
  "data_meaning": {
    "inputs": [
      {"text": "Давление в точках наблюдения на разных расстояниях от места возмущения и в разные моменты времени.", "claims": [], "hypothesis": true},
      {"text": "Коэффициент пьезопроводности κ пласта и время t с начала возмущения.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Оценка расстояния, за которым отклонение давления от начального значения пренебрежимо мало, при заданном t.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Порог, при котором отклонение считают малым, в тексте не задан.", "claims": [], "hypothesis": false},
      {"text": "Граница условна: разные пороги дают разные размеры зоны.", "claims": ["c1"], "hypothesis": true},
      {"text": "Неоднородность пласта и другие граничные условия могут менять вид затухания.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {"pack_id": null, "analogy": "Распространение обновления в распределённой системе: ближние узлы получают изменение раньше, дальние — позже, с затуханием. Можно считать «зоной обновления» область, где данные уже отличаются от исходных.", "breaks_where": "Давление распространяется не по сообщениям с задержкой и не дискретно. Граница зоны здесь задаётся порогом малости, а не событием.", "hypothesis": true},
  "now_nuance": null,
  "threshold": {"is_threshold": true, "why": "Без понимания, что возмущение локально и зона растёт со временем, нельзя читать результаты приближённых решений и выбирать расстояния для анализа."},
  "inefficiency": {
    "inputs": [
      {"text": "Расстояния до точек наблюдения и время с момента возмущения.", "hypothesis": true},
      {"text": "Коэффициент пьезопроводности пласта.", "hypothesis": true}
    ],
    "manual_steps": [
      {"text": "Выбрать порог малости отклонения вручную.", "hypothesis": true}
    ],
    "judgment_points": [
      {"text": "Где провести условную границу зоны при данном времени.", "hypothesis": true}
    ],
    "time": [
      {"text": "Пересчёт размера зоны при каждом новом моменте времени.", "hypothesis": true}
    ],
    "typical_errors": [
      {"text": "Считать границу резкой и постоянной по скорости, как у звука.", "hypothesis": true},
      {"text": "Принимать условную границу за реальный физический фронт.", "hypothesis": true}
    ]
  },
